var seed = Math.random() * 99999;
var particles = [];
var mySize, margin;

let colors0 = "fef9fb-fafdff-ffffff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
let colors7 = "fefefe-292929-222222-202020".split("-").map((a) => "#" + a);
let colors8 = "f7f6cf-b6d8f2-f4cfdf-9ac8eb-ccd4bf-e7cba9-eebab2-f5f3f7-f5e2e4-f4c815-f9cad7-A57283-c1d5de-deede6-AAD9CD-E8D595-E9BBB5-E7CBA9-8DA47E".split("-").map((a) => "#" + a);
let colors81 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
let color_sel1, color_sel2;
let bgcolor;
let rectcolor;

function setup() {
	frameRate(1);
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	margin = mySize / 100;
	createCanvas(mySize, mySize);
	bgcolor = random(colors0);
	rectcolor = random(colors81);
}

function draw() {
	background(bgcolor);
	rectMode(CENTER);
	push();
	translate(width / 2, height / 2);
	drawRectRecursive(0, 0, width, height, 5);
	pop();

	noFill();
	rectMode(CORNER);
	stroke(bgcolor);
	strokeWeight(mySize / 2);
	rect(0, 0, width, height);

}


function drawRectRecursive(x, y, h, w, depth) {
	noStroke();
	// fill(rectcolor);
	fill(str(rectcolor) + "40");
	// fill(str(random(colors7)) + "bf");
	let rio = 0.995;
	push();
	translate(x, y);
	drawingContext.shadowColor = random(colors7);
	drawingContext.shadowOffsetX = margin / 2;
	drawingContext.shadowOffsetY = margin / 2;
	drawingContext.shadowBlur = 0;
	rect(random(-margin, margin), random(-margin, margin), h * rio, w * rio);
	pop();
	if (depth > 1) {
		let offx = width / 2 - w / 2 * rio;
		let offy = height / 2 - w / 2 * rio;
		push();
		translate(-offx / 2, -offy / 2);
		drawRectRecursive(x, y, w / 2 * rio, h / 2 * rio, depth - 1);
		drawRectRecursive(x + w / 2, y, w / 2 * rio, h / 2 * rio, depth - 1);
		drawRectRecursive(x + w / 2, y + h / 2, w / 2 * rio, h / 2 * rio, depth - 1);
		drawRectRecursive(x, y + h / 2, w / 2 * rio, h / 2 * rio, depth - 1);
		pop();
	}
}

